  rewrite (morph_room_of_lt b Hroom), (desc_room_of_lt b Hdesc) in *. cbv beta iota in F_pc, F_mu, F_err, F_halted, F_regs, F_mem, F_error_code, F_cert_addr, F_partition_ops, F_mdl_ops, F_info_gain, F_mu_tensor, F_module_tensors, F_ptTable, F_pt_next_id, F_certified, F_wc_same_00, F_wc_diff_00, F_wc_same_01, F_wc_diff_01, F_wc_same_10, F_wc_diff_10, F_wc_same_11, F_wc_diff_11, F_morph_src_table, F_morph_dst_table, F_morph_coupling_desc_table, F_morph_identity_table, F_morph_valid_table, F_morph_next_id, F_coupling_desc_label_table, F_coupling_desc_label_len_table, F_lassert_phase, F_chsh_phase, F_mc_phase. rewrite !module_present_eqb in *. destruct (Nat.eqb (wordToNat (hw_ptTable b (split1 6 2 (bits8 b0 b1 b2 b3 b4 b5 b6 b7)))) 0) eqn:G1; destruct (Nat.eqb (wordToNat (hw_ptTable b (split1 6 26 (bits32 e0 e1 e2 e3 e4 e5 e6 e7 e8 e9 e10 e11 e12 e13 e14 e15 e16 e17 e18 e19 e20 e21 e22 e23 e24 e25 e26 e27 e28 e29 e30 e31)))) 0) eqn:G2; [ | | | exfalso; destruct Hfail as [H|H]; [apply Nat.eqb_neq in G1; exact (G1 H)|apply Nat.eqb_neq in G2; exact (G2 H)] ]; cbv beta iota delta [negb] in F_pc, F_mu, F_err, F_halted, F_regs, F_mem, F_error_code, F_cert_addr, F_partition_ops, F_mdl_ops, F_info_gain, F_mu_tensor, F_module_tensors, F_ptTable, F_pt_next_id, F_certified, F_wc_same_00, F_wc_diff_00, F_wc_same_01, F_wc_diff_01, F_wc_same_10, F_wc_diff_10, F_wc_same_11, F_wc_diff_11, F_morph_src_table, F_morph_dst_table, F_morph_coupling_desc_table, F_morph_identity_table, F_morph_valid_table, F_morph_next_id, F_coupling_desc_label_table, F_coupling_desc_label_len_table, F_lassert_phase, F_chsh_phase, F_mc_phase.
